sql.where:
k.status = 'ACTIVE'
and k.snapshot_year = #{criteria.baseYear}

    and (k.organization_code = #{criteria.normalizedOrganizationCode}
         or rel.parent_organization_code = #{criteria.normalizedOrganizationCode})


    and k.employee_no = #{criteria.normalizedEmployeeNo}


    and k.name ilike concat('%', #{criteria.normalizedName}, '%')

mapper.select:
select 


order by coalesce(college.organization_name, dept.organization_name), dept.organization_name, k.employee_no
limit #{criteria.safeSize} offset #{criteria.offset}
